#!/bin/bash
# Autogenerated deployment script for bio-bench
set -e
cd "$(dirname "$0")"

echo "=== Building web client for bio-bench ==="
cd web
npm install
npm run build
cd ..

echo "=== Deploying to Hostinger via rsync ==="
# Note: Ensure you have added 'hostinger-portfolio' to your SSH config.
# If using env vars: rsync -avz --delete web/dist/ $HOSTINGER_USER@$HOSTINGER_HOST:/home/u918475266/public_html/bio-bench/
rsync -avz --delete web/dist/ hostinger-portfolio:/home/u918475266/public_html/bio-bench/

echo "=== Deployment for bio-bench completed successfully ==="
